# Define the divisors of 60
divisors_of_60 = [1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60]

# Statement A: a must be a divisor of 60
def check_statement_A(divisors_of_60):
    for b in divisors_of_60:
        for a in divisors_of_60:
            if b % a != 0:
                return False  # a is not a divisor of 60
    return True

statement_A = check_statement_A(divisors_of_60)

# Statement B: 60 must be a multiple of b
def check_statement_B(divisors_of_60):
    for b in divisors_of_60:
        if 60 % b != 0:
            return False  # 60 is not a multiple of b
    return True

statement_B = check_statement_B(divisors_of_60)

# Statement C: b must be a factor of c
def check_statement_C(divisors_of_60):
    for b in divisors_of_60:
        for c in divisors_of_60:
            if b < c < 60 and c % b != 0:
                return False  # b is not a factor of c
    return True

statement_C = check_statement_C(divisors_of_60)

# Statement D: a cannot be 20
